from typing import Any, Iterable
import csv
import io
import os

REQUIRED_COLUMNS = ('name', 'email')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


def _cell_to_text(value: Any) -> str:
    if value is None:
        return ''
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()


def _read_csv_rows(data: bytes) -> tuple[list[str], Iterable[tuple[int, dict[str, Any]]]]:
    text = data.decode('utf-8-sig')
    reader = csv.DictReader(io.StringIO(text))
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    reader.fieldnames = header

    def rows():
        for row in reader:
            yield reader.line_num, row

    return header, rows()


def _read_excel_rows(data: bytes) -> tuple[list[str], Iterable[tuple[int, dict[str, Any]]]]:
    from openpyxl import load_workbook

    workbook = load_workbook(io.BytesIO(data), read_only=True, data_only=True)
    sheet = workbook.active
    iterator = sheet.iter_rows(values_only=True)
    first = next(iterator, None) or ()
    header = [_cell_to_text(h).lstrip('\ufeff').lower() for h in first]

    def rows():
        for number, values in enumerate(iterator, 2):
            if all(v is None or _cell_to_text(v) == '' for v in values):
                continue
            row = {header[i]: _cell_to_text(v) for i, v in enumerate(values) if i < len(header)}
            if any(_cell_to_text(v) for v in values[len(header):]):
                row[None] = True
            yield number, row

    return header, rows()


def validate_user_upload(data: bytes, filename: str, max_rows: int = MAX_ROWS) -> dict[str, Any]:
    """Validate an uploaded users export (.csv or .xlsx).

    Returns {'valid_users', 'invalid_rows', 'valid_count', 'invalid_count'}.
    Each invalid row is {'row': <row/line number in the file>, 'errors': [reasons]}.
    All rows are checked; validation does not stop at the first error.
    Row values are never echoed back in error messages.
    """
    extension = os.path.splitext(filename)[1].lower()
    try:
        if extension == '.csv':
            header, rows = _read_csv_rows(data)
        elif extension in ('.xlsx', '.xlsm'):
            header, rows = _read_excel_rows(data)
        else:
            return _report([], [{'row': 1, 'errors': [f'unsupported file type: {extension or "none"}']}])
    except Exception:
        return _report([], [{'row': 1, 'errors': ['file could not be read']}])

    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return _report([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])

    valid, errors, seen = [], [], set()
    try:
        for count, (row_number, row) in enumerate(rows, 1):
            if count > max_rows:
                errors.append({'row': row_number, 'errors': [f'more than {max_rows} rows; stopped']})
                break
            name = (row.get('name') or '').strip()
            email = (row.get('email') or '').strip().lower()
            age_raw = (row.get('age') or '').strip()
            local, _, domain = email.partition('@')
            problems = [] if name else ['name is required']
            if None in row:
                problems.append('too many fields')
            if (len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email
                    or '@' in domain or '.' not in domain.strip('.')):
                problems.append('email is invalid')
            elif email in seen:
                problems.append('duplicate email')
            if age_raw and not (age_raw.isdigit() and int(age_raw) <= 150):
                problems.append('age must be a whole number from 0 to 150')
            if problems:
                errors.append({'row': row_number, 'errors': problems})
            else:
                seen.add(email)
                valid.append({'name': name, 'email': email,
                              'age': int(age_raw) if age_raw else None})
    except Exception:
        errors.append({'row': 0, 'errors': ['file could not be fully read']})
    return _report(valid, errors)


def _report(valid: list[dict[str, Any]], errors: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        'valid_users': valid,
        'invalid_rows': errors,
        'valid_count': len(valid),
        'invalid_count': len(errors),
    }

